input.command:
node -e "
const convert = require('culori').default;

// Original colors
const blue = '#3b82f6';
const red = '#e94560';

const blueLch = convert(blue)('lch');
const redLch = convert(red)('lch');

console.log('Original:');
console.log('Blue:', JSON.stringify(blueLch, null, 2));
console.log('Red:', JSON.stringify(redLch, null, 2));

// Match saturation - use average
const targetSat = (blueLch.s + redLch.s) / 2;
console.log('\nTarget saturation:', targetSat.toFixed(2));

// Create new colors with matched saturation
const blueMatched = { ...blueLch, s: targetSat };
const redMatched = { ...redLch, s: targetSat };

const blueHex = convert(blueMatched)('hex');
const redHex = convert(redMatched)('hex');

console.log('\nMatched saturation:');
console.log('Blue hex:', blueHex);
console.log('Red hex:', redHex);
"

